begin;
select set_config('pv.owner',gen_random_uuid()::text,true),set_config('pv.other',gen_random_uuid()::text,true),set_config('pv.p',gen_random_uuid()::text,true),set_config('pv.u',gen_random_uuid()::text,true),set_config('pv.zero',gen_random_uuid()::text,true),set_config('pv.unknown',gen_random_uuid()::text,true),set_config('pv.s',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('pv.owner')::uuid,'variance-a@example.invalid'),(current_setting('pv.other')::uuid,'variance-b@example.invalid');
select set_config('request.jwt.claims',json_build_object('sub',current_setting('pv.owner'),'role','authenticated')::text,true);set local role authenticated;
insert into public.products(id,name,barcode,sale_price) values(current_setting('pv.p')::uuid,'Saved name','00123',1000),(current_setting('pv.u')::uuid,'Stock-only',null,1000),(current_setting('pv.zero')::uuid,'Zero cost',null,1000),(current_setting('pv.unknown')::uuid,'Unknown',null,1000);
insert into public.suppliers(id,name) values(current_setting('pv.s')::uuid,'Saved supplier');
do $$declare p uuid:=current_setting('pv.p')::uuid;u uuid:=current_setting('pv.u')::uuid;z uuid:=current_setting('pv.zero')::uuid;k uuid:=current_setting('pv.unknown')::uuid;s uuid:=current_setting('pv.s')::uuid;
 a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();ua uuid:=gen_random_uuid();ub uuid:=gen_random_uuid();za uuid:=gen_random_uuid();ka uuid:=gen_random_uuid();shared uuid:=gen_random_uuid();x jsonb;v bigint;stock bigint;cash bigint;debt bigint;today date:=(now() at time zone 'Asia/Baghdad')::date;begin
 x:=public.get_purchase_return_variance(today,today);if x->>'count'<>'0' or x->'groups'->'tracked'->>'complete'<>'true' then raise exception 'empty';end if;
 perform public.post_supplier_purchase(a,jsonb_build_array(jsonb_build_object('product_id',p,'quantity_units',1000,'unit_cost',500)),s,0,'A','credit');
 perform public.post_supplier_purchase(b,jsonb_build_array(jsonb_build_object('product_id',p,'quantity_units',1000,'unit_cost',1500)),s,0,'B','credit');
 perform public.post_purchase_return(shared,a,'partial cost difference',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',500)));
 perform public.post_purchase_return(shared,a,'partial cost difference',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',500)));
 perform public.post_purchase_reversal(shared,b,'full cost difference');
 perform public.post_purchase(ua,jsonb_build_array(jsonb_build_object('product_id',u,'quantity_units',1000,'unit_cost',2000)),'stock supplier','','');
 perform public.post_purchase(ub,jsonb_build_array(jsonb_build_object('product_id',u,'quantity_units',1000,'unit_cost',4000)),'stock supplier','','');
 perform public.post_purchase_return(gen_random_uuid(),ua,'untracked difference',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',500)));
 perform public.post_purchase(za,jsonb_build_array(jsonb_build_object('product_id',z,'quantity_units',1,'unit_cost',1)),'','','');perform public.post_purchase_reversal(gen_random_uuid(),za,'genuine zero');
 perform public.post_stock_adjustment(gen_random_uuid(),k,0,0,1000,'unknown opening');
 perform public.post_purchase(ka,jsonb_build_array(jsonb_build_object('product_id',k,'quantity_units',1000,'unit_cost',1000)),'','','');perform public.post_purchase_return(gen_random_uuid(),ka,'unknown basis',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',500)));
 update public.products set name='Changed catalogue name' where id=p;update public.suppliers set name='Changed supplier' where id=s;
 select sum(quantity_units) into stock from public.product_stock;select coalesce(sum(delta),0) into cash from public.cash_movements;select sum(balance) into debt from public.supplier_balances;
 x:=public.get_purchase_return_variance(today,today);
 if x->>'count'<>'5' or x->>'known_count'<>'4' then raise exception 'coverage';end if;
 if x->'groups'->'tracked'->>'document_count'<>'2' or x->'groups'->'tracked'->>'document_value'<>'1750' or x->'groups'->'tracked'->>'known_cost'<>'1500' or x->'groups'->'tracked'->>'known_variance'<>'250' or x->'groups'->'tracked'->>'complete'<>'true' then raise exception 'tracked totals';end if;
 if x->'groups'->'untracked'->>'document_value'<>'1500' or x->'groups'->'untracked'->>'known_value'<>'1000' or x->'groups'->'untracked'->>'known_cost'<>'1500' or x->'groups'->'untracked'->>'known_variance'<>'-500' or x->'groups'->'untracked'->>'complete'<>'false' then raise exception 'untracked totals';end if;
 if not exists(select 1 from jsonb_array_elements(x->'rows') r where r->>'mode'='tracked' and r->>'variance'='-250' and r->>'name'='Saved name' and r->>'supplier_name'='Saved supplier') then raise exception 'negative variance or saved names';end if;
 if not exists(select 1 from jsonb_array_elements(x->'rows') r where r->>'product_id'=z::text and r->>'stock_cost'='0' and r->>'variance'='0') then raise exception 'known zero';end if;
 if not exists(select 1 from jsonb_array_elements(x->'rows') r where r->>'product_id'=k::text and r->'stock_cost'='null'::jsonb and r->'variance'='null'::jsonb) then raise exception 'unknown guessed';end if;
 if (select sum(quantity_units) from public.product_stock)<>stock or (select coalesce(sum(delta),0) from public.cash_movements)<>cash or (select sum(balance) from public.supplier_balances)<>debt then raise exception 'read changed business';end if;
 begin perform public.get_purchase_return_variance(today,today+366);raise exception 'range accepted';exception when raise_exception then if sqlerrm<>'variance_invalid_range' then raise;end if;end;
end $$;
reset role;select set_config('request.jwt.claims',json_build_object('sub',current_setting('pv.other'),'role','authenticated')::text,true);set local role authenticated;
do $$declare today date:=(now() at time zone 'Asia/Baghdad')::date;begin if public.get_purchase_return_variance(today,today)->>'count'<>'0' then raise exception 'cross owner';end if;end $$;
reset role;select set_config('request.jwt.claims','{}',true);set local role authenticated;
do $$begin begin perform public.get_purchase_return_variance('2026-10-18','2026-10-18');raise exception 'no uid';exception when raise_exception then if sqlerrm<>'variance_auth_required' then raise;end if;end;end $$;
reset role;set local role anon;
do $$begin begin perform public.get_purchase_return_variance('2026-10-18','2026-10-18');raise exception 'anon';exception when insufficient_privilege then null;end;end $$;
reset role;
select 'PASS: full/partial shared UUIDs, saved names, signed variance, credit/untracked split, unknown/zero coverage, replay, no writes and owner isolation' as verification;
rollback;
